import { forwardRef, type ButtonHTMLAttributes } from "react";

const cn = (...values: Array<string | false | null | undefined>) => values.filter(Boolean).join(" ");

export type ButtonVariant = "primary" | "secondary" | "ghost" | "danger";
export type ButtonSize = "sm" | "md" | "lg";

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  loading?: boolean;
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button(
  { variant = "primary", size = "md", loading = false, disabled, children, className, ...props },
  ref,
) {
  return (
    <button
      ref={ref}
      className={cn("ds-button", `ds-button--${variant}`, `ds-button--${size}`, className)}
      disabled={disabled || loading}
      {...props}
    >
      {loading ? "Loading…" : children}
    </button>
  );
});

Button.displayName = "Button";

.ds-button {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 12px;
  border: 1px solid transparent;
  border-radius: 6px;
  cursor: pointer;
  font: 600 14px/20px system-ui, sans-serif;
  white-space: nowrap;
  transition: background .15s ease, border-color .15s ease, box-shadow .15s ease, color .15s ease;
}
.ds-button:focus-visible { outline: 0; box-shadow: 0 0 0 2px rgb(79 134 181 / 25%); }
.ds-button:disabled { cursor: not-allowed; opacity: .6; }
.ds-button--primary { color: #fff; background: #4f86b5; }
.ds-button--primary:hover:not(:disabled) { background: #3f739f; }
.ds-button--secondary { color: #1f2937; border-color: #d4d9e0; background: #fff; }
.ds-button--secondary:hover:not(:disabled) { background: #f3f5f7; }
.ds-button--ghost { color: #3f739f; background: transparent; }
.ds-button--danger { color: #fff; background: #c75757; }
.ds-button--sm { min-height: 28px; padding-inline: 10px; font-size: 12px; line-height: 16px; }
.ds-button--lg { min-height: 40px; padding-inline: 16px; }

import type { Meta, StoryObj } from "@storybook/react-vite";
import { Button } from "./button";

const meta = {
  title: "Components/Core/Button",
  component: Button,
  tags: ["autodocs"],
  parameters: { layout: "centered" },
  argTypes: {
    variant: { control: "select", options: ["primary", "secondary", "ghost", "danger"] },
    size: { control: "select", options: ["sm", "md", "lg"] },
    loading: { control: "boolean" },
    disabled: { control: "boolean" },
    children: { control: "text" },
  },
  args: { variant: "primary", size: "md", children: "Button", loading: false, disabled: false },
} satisfies Meta<typeof Button>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {};
export const Secondary: Story = { args: { variant: "secondary" } };
export const Ghost: Story = { args: { variant: "ghost" } };
export const Danger: Story = { args: { variant: "danger" } };
export const Loading: Story = { args: { variant: "secondary", loading: true } };
export const Disabled: Story = { args: { disabled: true } };
export const Small: Story = { args: { size: "sm" } };
export const Large: Story = { args: { size: "lg" } };
